import { paperToneParams } from "./tone-field";
import type { TileRegion, XuanPaperScene } from "./types";

// Base64-encoded WASM binary built from wasm/xuan-paper-tone:
//   cargo build --release --target wasm32-unknown-unknown
//   wasm-opt -O3 --enable-bulk-memory --enable-nontrapping-float-to-int \
//     --enable-sign-ext --enable-mutable-globals \
//     target/wasm32-unknown-unknown/release/xuan_paper_tone.wasm -o <out>.wasm
// then base64-encode <out>.wasm into the string below.
const WASM_BASE64 =
  "";

interface PaperToneExports {
  memory: WebAssembly.Memory;
  outline_buffer: (len: number) => number;
  render_paper_tone: (
    tileWidth: number,
    tileHeight: number,
    tileX: number,
    tileY: number,
    fullWidth: number,
    fullHeight: number,
    baseR: number,
    baseG: number,
    baseB: number,
    toneSeed: number,
    formationSeed: number,
    detailSeed: number,
    agingSeed: number,
    textureBoost: number,
    grainBoost: number,
    absorbencyBoost: number,
    ageAmount: number,
    deckleRough: number,
  ) => number;
}

let cachedModule: WebAssembly.Module | null = null;
let cachedExports: PaperToneExports | null = null;

function base64Decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

const wasmCompilePromise: Promise<WebAssembly.Module | null> =
  typeof WebAssembly !== "undefined"
    ? WebAssembly.compile(base64Decode(WASM_BASE64).buffer as ArrayBuffer)
        .then((m) => {
          cachedModule = m;
          return m;
        })
        .catch(() => null)
    : Promise.resolve(null);

export const ready: Promise<boolean> = wasmCompilePromise.then((m) => m !== null);

function getExports(): PaperToneExports | null {
  if (cachedExports) {
    return cachedExports;
  }
  if (!cachedModule && typeof WebAssembly !== "undefined") {
    try {
      cachedModule = new WebAssembly.Module(base64Decode(WASM_BASE64).buffer as ArrayBuffer);
    } catch {
      return null;
    }
  }
  if (!cachedModule) {
    return null;
  }
  try {
    const instance = new WebAssembly.Instance(cachedModule);
    cachedExports = instance.exports as unknown as PaperToneExports;
    return cachedExports;
  } catch {
    return null;
  }
}

function uploadOutline(exports: PaperToneExports, scene: XuanPaperScene): void {
  const outline = scene.deckleOutline;
  if (!outline) return;
  const { width, height } = scene.options;
  const len = 2 * (width + 1) + 2 * (height + 1);
  const ptr = exports.outline_buffer(len);
  // Create the view after the call: outline_buffer may grow memory.
  const view = new Float32Array(exports.memory.buffer, ptr, len);
  let offset = 0;
  for (const side of [outline.top, outline.bottom, outline.left, outline.right]) {
    const sideLen = side === outline.top || side === outline.bottom ? width + 1 : height + 1;
    for (let i = 0; i < sideLen; i++) {
      view[offset + i] = side[i] ?? 0;
    }
    offset += sideLen;
  }
}

/**
 * Renders the paper tone (base colour, formation, grain, ageing and deckle
 * alpha) for the whole sheet or one tile, entirely inside WASM memory.
 *
 * The returned pixel array is a view on WASM memory and is only valid until
 * the next call into this module; hand it straight to `putImageData` (or copy
 * it) before rendering anything else. Returns null when WASM is unavailable.
 */
export function renderPaperToneWasm(
  scene: XuanPaperScene,
  tile: TileRegion | null,
): Uint8ClampedArray | null {
  const exports = getExports();
  if (!exports) {
    return null;
  }

  const { width, height } = scene.options;
  const tw = tile ? tile.width : width;
  const th = tile ? tile.height : height;
  const p = paperToneParams(scene);

  if (p.deckleRough >= 0) {
    uploadOutline(exports, scene);
  }

  const ptr = exports.render_paper_tone(
    tw,
    th,
    tile ? tile.x : 0,
    tile ? tile.y : 0,
    width,
    height,
    p.baseR,
    p.baseG,
    p.baseB,
    scene.seeds.tone,
    scene.seeds.formation,
    scene.seeds.detail,
    scene.seeds.aging,
    p.textureBoost,
    p.grainBoost,
    p.absorbencyBoost,
    p.ageAmount,
    p.deckleRough,
  );

  return new Uint8ClampedArray(exports.memory.buffer, ptr, tw * th * 4);
}
